   if (isCar(vehicle)) {
       // TypeScript narrows 'vehicle' to 'Car'
       console.log(`Car with ${vehicle.wheels} wheels.`);
   } else {
       // TypeScript narrows 'vehicle' to 'Bike'
       console.log(`Bike with ${vehicle.pedals} pedals.`);
   }
}

describeVehicle({ type: "car", wheels: 4 }); // Output: Car with 4 wheels.
describeVehicle({ type: "bike", pedals: 2 }); // Output: Bike with 2 pedals.

