}

type Payment =
   | { status: "success"; amount: number }
   | { status: "failure"; reason: string }
   | { status: "pending" };

function handlePayment(payment: Payment) {
   switch (payment.status) {
       case "success":
           console.log(`Payment succeeded with amount: ${payment.amount}`);
           break;
       case "failure":
           console.log(`Payment failed due to: ${payment.reason}`);
           break;
       case "pending":
           console.log("Payment is still pending.");
           break;
   }
}

handlePayment({ status: "success", amount: 100 });  // Output: Payment succeeded with amount: 100
handlePayment({ status: "failure", reason: "Insufficient funds" }); // Output: Payment failed due to: Insufficient funds

